15	  // ---------- 读当前店铺名（右上角英文店名） ----------
16	  function findStoreNameEl() {
17	    const W = window.innerWidth;
18	    let best = null;
19	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
20	      const t = (el.textContent || '').trim();
21	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
