23	      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
24	      if (el.children.length > 2) continue;
25	      const r = el.getBoundingClientRect();
26	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
27	      if (r.left < W * 0.5) continue;
28	      if (!best || r.left > best.left) best = { el, left: r.left };
29	    }
30	    return best ? best.el : null;
31	  }
32	  function readStoreName() { const el = findStoreNameEl(); return el ? (el.textContent || '').trim() : null; }
33	
34	  // ---------- 转发接口响应 ----------
35	  window.addEventListener('message', (e) => {
36	    if (e.source !== window) return;
37	    const d = e.data;
38	    if (!d || d.__temuMon !== true) return;
39	    try { chrome.runtime.sendMessage({ type: 'capture', kind: d.kind, url: d.url, body: d.body, store: readStoreName() }); } catch (err) {}
40	  });
