42	  // ---------- 读流量异常：两类「快速筛选」chip 的计数 ----------
43	  // 两个 chip 是常驻筛选项：「商品流量待关注 N」「商品流量近期有下降 N」，各带自己的数字。
44	  // 关键：不能靠"标签文本是否存在"判断有无异常——标签一直在，只有 N>0 才是真有异常。
45	  // （之前用存在性判断，导致每个店都误报"流量下降 有"。）
46	  function readChipCount(all, label) {
47	    const re = new RegExp(label);
48	    const labels = all
49	      .filter((e) => re.test(e.textContent || '') && (e.textContent || '').trim().length < 24)
50	      .sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
51	    for (const el of labels) {
52	      // 标签后允许 0~3 个非数字字符（空格/冒号/括号），避免误吞相邻 chip 的数字
53	      for (const cand of [el, el.parentElement, el.parentElement && el.parentElement.parentElement]) {
54	        if (!cand) continue;
55	        const m = (cand.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
56	        if (m) return Number(m[1].replace(/,/g, ''));
57	      }
58	      // 数字在标签之后的独立兄弟徽标里（未与标签拼接进同一文本）
59	      let sib = el.nextElementSibling;
60	      for (let i = 0; i < 3 && sib; i++, sib = sib.nextElementSibling) {
61	        const st = (sib.textContent || '').trim();
62	        if (/^[\d,]+$/.test(st)) return Number(st.replace(/,/g, ''));
63	      }
64	    }
65	    return null; // 读不到 → 未知（不当作 0，也不当作"有"）
66	  }
67	  // 「商品流量近期有下降」不是带计数的筛选 chip，而是逐行的红色徽标（列「商品优化事项」下）。
68	  // 因此按"当前页可见的行内徽标个数"来统计。注意：只覆盖当前页（默认 20 条/页），
69	  // 下降商品若在其它页则数不到——被动读数的固有限制，要精确总数得点筛选（主动模式）。
70	  function countDeclineBadges(all) {
71	    let n = 0;
72	    for (const e of all) {
73	      const t = (e.textContent || '').trim();
74	      if (!/商品流量近期有下降/.test(t) || t.length > 20) continue;
75	      // 只数最内层节点，避免父容器重复计数
76	      if ([...e.children].some((c) => /商品流量近期有下降/.test(c.textContent || ''))) continue;
77	      const r = e.getBoundingClientRect();
78	      if (r.width > 0 && r.height > 0) n++; // 只数真正渲染出来的行徽标，排除隐藏的筛选项/图例
79	    }
80	    return n;
81	  }
82	  function readTraffic() {
83	    const all = [...document.querySelectorAll('*')];
84	    return {
85	      watch: readChipCount(all, '商品流量待关注'),
86	      decline: countDeclineBadges(all),
87	    };
88	  }
89	  let tries = 0;
90	  const iv = setInterval(() => {
91	    tries++;
92	    // 商品表格是否已渲染出行——下降徽标在行里，必须等行出来再数，否则会在徽标出现前就读成 0
93	    const gridReady = !!document.querySelector('[data-testid="beast-core-table-body-tr"]');
94	    const { watch, decline } = readTraffic();
95	    const msg = { type: 'chipStats', store: readStoreName() };
96	    if (watch != null) msg.trafficWatch = watch;
97	    if (gridReady) msg.trafficDecline = decline; // 仅在表格渲染后 decline 才可信
98	    if (msg.trafficWatch != null || 'trafficDecline' in msg) {
99	      try { chrome.runtime.sendMessage(msg); } catch (e) {}
100	    }
101	    // 待关注读到且表格已渲染即定稿；否则最长约 40s
102	    if ((watch != null && gridReady) || tries > 20) clearInterval(iv);
103	  }, 2000);
