105	  // ---------- 切店自动化（轮巡用，由后台指令驱动） ----------
106	  async function waitFor(fn, timeout, step) {
107	    const t0 = Date.now();
108	    for (;;) { let r; try { r = fn(); } catch (e) { r = null; } if (r) return r; if (Date.now() - t0 > (timeout || 6000)) return null; await sleep(step || 200); }
109	  }
110	  function textEls(re, maxLen) {
111	    return [...document.querySelectorAll('*')].filter((e) => { const t = (e.textContent || '').trim(); return re.test(t) && t.length <= (maxLen || 40); });
112	  }
113	  function innermost(els) { return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null; }
114	  function clickableAncestor(el) { let n = el; for (let i = 0; i < 5 && n; i++) { if (n.tagName === 'BUTTON' || n.tagName === 'A' || n.getAttribute('role') === 'button') return n; n = n.parentElement; } return el; }
115	  // 完整鼠标事件序列（很多组件要 mousedown/up 才触发，单纯 click 不生效）
116	  function realClick(el) {
117	    if (!el) return false;
118	    const opts = { bubbles: true, cancelable: true, view: window };
119	    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
120	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
121	      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
122	    }
123	    try { el.click(); } catch (e) {}
124	    return true;
125	  }
126	  function modalOpen() { return textEls(/切换店铺|您的账户存在/, 20).length > 0; }
127	  function closeModal() {
128	    const x = document.querySelector('[aria-label="Close"],[aria-label="关闭"],.beast-core-modal-close,.semi-modal-close,.SnowModal_closeIcon');
129	    if (x) { realClick(x); return; }
130	    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
131	  }
132	
133	  // 压缩输出某元素的 HTML 骨架（去 style/data 属性），便于回传诊断
134	  function domSkel(el, maxLen) {
135	    if (!el) return 'null';
136	    let h = (el.outerHTML || '');
137	    h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
138	    return h.slice(0, maxLen || 2200);
139	  }
140	
141	  function visible(el) { const b = el.getBoundingClientRect(); return b.width > 0 && b.height > 0; }
142	
143	  async function openStoreModal(diag) {
144	    diag = diag || [];
145	    if (modalOpen()) { diag.push('弹窗已开'); return true; }
146	    const nameEl = findStoreNameEl();
147	    diag.push('店名=' + (nameEl ? (nameEl.textContent || '').trim() : 'null'));
148	    if (nameEl) {
149	      // 只点一次触发下拉：点店名的可点祖先 + 店名右侧箭头坐标（避免多次点击把下拉又关掉）
150	      const r = nameEl.getBoundingClientRect();
151	      realClick(clickableAncestor(nameEl));
152	      const el = document.elementFromPoint(Math.min(window.innerWidth - 3, r.right + 14), r.top + r.height / 2);
153	      if (el && el !== nameEl) realClick(el);
154	    }
155	    // 下拉里“切换”按钮：只认可见的、精确文本“切换”，取最后一个（下拉通常在 DOM 靠后）
156	    const sw = await waitFor(() => {
157	      const cands = textEls(/^切换$/, 6).filter(visible);
158	      return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
159	    }, 3500);
160	    diag.push('下拉切换按钮=' + !!sw);
161	    if (sw) realClick(sw);
162	    const ok = !!(await waitFor(() => (modalOpen() ? true : null), 4500));
163	    diag.push('弹窗打开=' + ok);
164	    if (!ok) {
165	      const cands = textEls(/切换/, 8).map((e) => {
166	        const b = e.getBoundingClientRect();
167	        return e.tagName + '.' + String(e.className || '').split(' ')[0] + '[' + (e.textContent || '').trim().slice(0, 6) + ',y' + Math.round(b.top) + ',w' + Math.round(b.width) + ']';
168	      });
169	      diag.push('切换候选(' + cands.length + ')=' + cands.join(' '));
170	      diag.push('模态计数 切换店铺=' + textEls(/切换店铺/, 20).length + ' 您的账户=' + textEls(/您的账户/, 40).length);
171	    }
172	    return ok;
173	  }
174	
175	  async function listStores() {
176	    if (!(await openStoreModal())) return [];
177	    await sleep(500);
178	    // 每个店铺行都带“半托管/全托管”标签；据此定位店名，避开背景页面的杂项英文
179	    const tags = textEls(/托管/, 6).filter(visible);
180	    const names = [];
181	    for (const tag of tags) {
182	      let row = tag.parentElement;
183	      for (let i = 0; i < 4 && row; i++) {
184	        const en = [...row.querySelectorAll('span,div,p,a')]
185	          .map((e) => (e.textContent || '').trim())
186	          .find((t) => /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) && t.length >= 2 && t.length <= 30 && !/^(NEW|Beta)$/i.test(t));
187	        if (en) { names.push(en); break; }
188	        row = row.parentElement;
189	      }
190	    }
191	    closeModal();
192	    const uniq = [...new Set(names)];
193	    LOG('listStores =>', uniq);
194	    return uniq;
195	  }
196	
197	  async function switchTo(target) {
198	    const diag = [];
199	    if (!(await openStoreModal(diag))) return { ok: false, msg: '打不开弹窗 | ' + diag.join(' ; ') };
200	    await sleep(300);
201	    const esc = String(target).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
202	    const rows = textEls(new RegExp(esc), 120).filter((e) => /切换/.test(e.textContent || ''));
203	    const row = innermost(rows);
204	    if (!row) { closeModal(); return { ok: false, msg: '弹窗里没找到店铺 ' + target }; }
205	    let btn = [...row.querySelectorAll('button,[role=button]')].find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
206	    if (!btn) {
207	      const cands = textEls(/^切换$/, 6).map(clickableAncestor).filter((b) => b && !b.disabled);
208	      btn = cands.find((b) => row.contains(b) || (b.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_CONTAINED_BY)) || null;
209	    }
210	    if (!btn) { closeModal(); return { ok: false, msg: '没找到可点的切换按钮(' + target + ')，可能已是当前店' }; }
211	    LOG('switchTo click', target);
212	    realClick(btn); // 触发切店（SPA 更新或整页重载）
213	    return { ok: true, msg: '已点击切换到 ' + target };
214	  }
215	
216	  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
217	    if (!msg || !msg.cmd) return;
218	    (async () => {
219	      try {
220	        if (msg.cmd === 'ping') { sendResponse({ store: readStoreName() }); return; }
221	        if (msg.cmd === 'listStores') { sendResponse({ names: await listStores() }); return; }
222	        if (msg.cmd === 'switchTo') { sendResponse(await switchTo(msg.target)); return; }
223	      } catch (e) { sendResponse({ ok: false, msg: String((e && e.message) || e) }); }
224	    })();
225	    return true;
226	  });
227	})();
