294	  chrome.alarms.create('poll', { periodInMinutes: Math.max(1, cfg.intervalMinutes || 15) });
295	}
296	chrome.runtime.onInstalled.addListener(setupAlarm);
297	chrome.runtime.onStartup.addListener(setupAlarm);
298	chrome.storage.onChanged.addListener((changes, area) => { if (area === 'local' && changes.config) setupAlarm(); });
