②「哪条链接下架」写好了。逻辑模拟全过，但**最脆的一环是"自动点『在售中』tab 再扫描"**——跟①一样，先在 Console 单独验一下这一步能不能跑通，再信任整个轮巡。

## 先验"点在售中 tab + 扫在售清单"（在某个店的 goods/list 页跑）

```js
(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const vis = e => { const b = e.getBoundingClientRect(); return b.width > 0 && b.height > 0; };
  const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(vis);
  const onSale = labels.find(e => /^在售中/.test((e.textContent || '').trim()));
  console.clear();
  console.log('找到在售中tab:', onSale ? onSale.textContent.trim() : '❌没找到');
  if (onSale) {
    for (const t of ['pointerdown', 'mousedown', 'mouseup', 'click'])
      onSale.dispatchEvent(new MouseEvent(t, { bubbles: true, cancelable: true, view: window }));
    await sleep(2500);
  }
  const rows = [...document.querySelectorAll('[data-testid="beast-core-table-body-tr"]')];
  const prods = []; let cur = null;
  for (const tr of rows) {
    const t = tr.textContent || ''; const spu = t.match(/SPU\s*ID[:：]\s*(\d+)/);
    if (spu) {
      const info = [...tr.querySelectorAll('td')].find(td => /SPU\s*ID/.test(td.textContent || '')) || tr;
      const nm = [...info.querySelectorAll('*')].map(e => (e.textContent || '').trim())
        .filter(x => x.length >= 6 && x.length <= 80 && /[一-龥]/.test(x) && !/^.{0,6}[:：]/.test(x) && !/SPU|SKC/.test(x))
        .sort((a, b) => b.length - a.length)[0] || '';
      cur = { productId: spu[1], name: nm }; prods.push(cur);
    }
  }
  const out = ['在售扫到 ' + prods.length + ' 个:', ...prods.map(p => '  ' + p.name.slice(0, 18) + ' | ' + p.productId)];
  const s = out.join('\n'); console.log(s); try { copy(s); } catch (e) {}
})();
```

